{"implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]

    # Validate required fields
    required_seg_fields = ("name", "importance", "minimum", "capacity")
    for i, seg in enumerate(segments):
        for field in required_seg_fields:
            if field not in seg:
                raise ValueError(f"Segment {i} missing required field '{field}'")

    if not isinstance(budget, int):
        raise ValueError("budget must be an integer")

    n = len(segments)
    names = [seg["name"] for seg in segments]
    importances = [seg["importance"] for seg in segments]
    minimums = [seg["minimum"] for seg in segments]
    capacities = [seg["capacity"] for seg in segments]

    quota_sum = sum(minimums)
    capacity_sum = sum(capacities)

    if budget < quota_sum:
        raise ValueError(
            f"Budget {budget} is below the minimum quota sum {quota_sum}"
        )
    if budget > capacity_sum:
        raise ValueError(
            f"Budget {budget} exceeds total capacity {capacity_sum}"
        )

    # Initialise every segment at its minimum quota
    allocs = list(minimums)
    remaining = budget - quota_sum

    # Greedy allocation: each step give one token to the segment
    # maximising importance / current_allocation; break ties by
    # original segment order (lower index wins).
    while remaining > 0:
        best_idx = -1
        best_priority = None
        for i in range(n):
            if allocs[i] >= capacities[i]:
                continue
            priority = importances[i] / allocs[i]  # next-position marginal value
            if best_idx == -1 or priority > best_priority:
                best_priority = priority
                best_idx = i
        if best_idx == -1:
            raise ValueError(
                "Remaining budget cannot be allocated: all segments at capacity"
            )
        allocs[best_idx] += 1
        remaining -= 1

    by_name = {names[i]: allocs[i] for i in range(n)}
    total = sum(allocs)

    return {
        "allocations": allocs,
        "by_name": by_name,
        "total": total,
    }
"}
